    if (/\btakes?[\s-]+(?:two|2)\s+interactive\b/i.test(seed)) known.push("TTWO");
    const explicit = seed.match(/\b[A-Z]{2,5}(?:\.[A-Z]{1,3})?\b/g) || [];
    return [...new Set([...known, ...explicit])];
